contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(address target, uint value, bytes calldata data, bytes32 predecessor, bytes32 salt, uint256 delay) public {
        require(!c.isOperation(c.hashOperation(target, value, data, predecessor, salt)), "already scheduled");
        require(delay >= c.getMinDelay(), "delay too small");
        require(delay >= 2, "delay too small");
        bytes32 id = c.hashOperation(target, value, data, predecessor, salt);
        c.schedule(target, value, data, predecessor, salt, delay);
        uint256 ts = c.getTimestamp(id);
        assert(ts == block.timestamp + delay && c.isOperationPending(id) && !c.isOperationReady(id) && !c.isOperationDone(id) && c.isOperation(id));
    }
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(address target, uint256 value, bytes calldata data, bytes32 predecessor, bytes32 salt, uint256 delay) public {
        require(delay >= c.getMinDelay(), "delay too small");
        bytes32 id = c.hashOperation(target, value, data, predecessor, salt);
        require(!c.isOperation(id), "already scheduled");
        c.grantRole(c.PROPOSER_ROLE(), address(this));
        c.schedule(target, value, data, predecessor, salt, delay);
        require(c.isOperationPending(id), "must be pending before cancel");
        c.cancel(id);
        assert(c.getTimestamp(id) == 0 && !c.isOperation(id) && !c.isOperationPending(id) && !c.isOperationDone(id) && !c.isOperationReady(id));
    }
    receive() external payable {}
}

