contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(bytes32 role, address account) public {
        // The test contract deployed c, so it holds TIMELOCK_ADMIN_ROLE,
        // which is the admin role of PROPOSER_ROLE.
        bool beforeHas = c.hasRole(role, account);
        bool isAdmin = c.hasRole(c.TIMELOCK_ADMIN_ROLE(), address(this));

        bool reverted;
        try c.grantRole(role, account) {
            reverted = false;
        } catch {
            reverted = true;
        }

        bool afterHas = c.hasRole(role, account);
        assert(isAdmin ? (!reverted && !beforeHas && afterHas) : reverted);
    }

    receive() external payable {}
}

